G[24]='Bringt Schattumbras Kopf zu Senani Thunderheart im Splintertreeposten in Ashenvale.'
G[25]='Erledigt 12 beschmutzte Wasserelementare am Mystralsee östlich vom Steinkrallenpfad und südwestlich vom Splintertreeposten.$B$BErkundet den Pavillon am Mystralsee, der den nahen Außenposten der Allianz überblickt.$B$BKehrt zu Mastok Wrilehiss im Splintertreeposten in Ashenvale zurück.'
G[26]='Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade.'
G[27]='Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade.'
G[28]="Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.$B$BIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen."
G[29]="Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.$B$BIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen."
G[30]='Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.$B$BFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.$B$BBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.'
G[31]='Kehrt nach Thunder Bluff zurück und zeigt Turak Runetotem den Anhänger des Seelöwen.'
G[33]='Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch.'
G[34]='Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis.'
G[35]='Marshal Dughan möchte, dass Ihr mit Wache Thomas sprecht.'
G[36]='Verna Furlbrow möchte, dass Ihr ihr Rezept für Westfall-Eintopf bei Salma Saldean abliefert.'
G[37]='Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht.'
