G[2478]="Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.$B$BEliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben."
G[2479]='Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.$B$BUm nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!'
